import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    words = input_data[1:n+1]

    MOD = 10**9 + 7

    def get_options(s):
        opts = set()
        for i in range(len(s)):
            opts.add(s[:i] + s[i+1:])
        return sorted(opts)

    if n == 0:
        print(0)
        return

    prev_opts = get_options(words[0])
    if not prev_opts:
        print(0)
        return

    count = 1

    for i in range(1, n):
        curr_opts = get_options(words[i])
        if not curr_opts:
            print(0)
            return

        valid_next = []
        for opt in curr_opts:
            if opt >= prev_opts[-1]:
                valid_next.append(opt)

        if not valid_next:
            print(0)
            return

        valid_next.sort()
        count = (count * len(valid_next)) % MOD
        prev_opts = valid_next

    print(count)

solve()
